  "captions": {
    "source": "films/diwali-north/captions.srt",
    "lines": [
      {
        "id": "v01.1",
        "text": "Why do we light",
        "start": 0,
        "end": 0.9
      },
      {
        "id": "v01.2",
        "text": "so many lamps? the",
        "start": 0.9,
        "end": 1.8
      },
      {
        "id": "v01.3",
        "text": "child asks.",
        "start": 1.8,
        "end": 2.7333333333333334
      },
      {
        "id": "v02.1",
        "text": "Because a whole city",
        "start": 3.3666666666666667,
        "end": 4.266666666666667
      },
      {
        "id": "v02.2",
        "text": "once waited for someone",
        "start": 4.266666666666667,
        "end": 5.166666666666667
      },
      {
        "id": "v02.3",
        "text": "to come home.",
        "start": 5.166666666666667,
        "end": 5.966666666666667
      },
      {
        "id": "v03.1",
        "text": "In North India, Diwali",
        "start": 6.4,
        "end": 7.3
      },
      {
        "id": "v03.2",
        "text": "remembers Rama's return to",
        "start": 7.3,
        "end": 8.2
      },
      {
        "id": "v03.3",
        "text": "Ayodhya",
        "start": 8.2,
        "end": 9.733333333333333
      },
      {
        "id": "v04.1",
        "text": "with Sita and Lakshmana,",
        "start": 10.166666666666666,
        "end": 11.066666666666666
      },
      {
        "id": "v04.2",
        "text": "after fourteen years of",
        "start": 11.066666666666666,
        "end": 11.966666666666667
      },
      {
        "id": "v04.3",
        "text": "exile and his victory",
        "start": 11.966666666666667,
        "end": 12.866666666666667
      },
      {
        "id": "v04.4",
        "text": "over Ravana.",
        "start": 12.866666666666667,
        "end": 15
      },
      {
        "id": "v05.1",
        "text": "On the darkest night",
        "start": 15.5,
        "end": 16.4
      },
      {
        "id": "v05.2",
        "text": "of Kartik, the people",
        "start": 16.4,
        "end": 17.3
      },
      {
        "id": "v05.3",
        "text": "cleaned their homes,",
        "start": 17.3,
        "end": 18.366666666666667
      },
      {
        "id": "v06.1",
        "text": "lit a diya at",
        "start": 18.933333333333334,
        "end": 19.833333333333332
      },
      {
        "id": "v06.2",
        "text": "every door, and the",
        "start": 19.833333333333332,
        "end": 20.733333333333334
      },
      {
        "id": "v06.3",
        "text": "road home became a",
        "start": 20.733333333333334,
        "end": 21.633333333333333
      },
      {
        "id": "v06.4",
        "text": "river of light.",
        "start": 21.633333333333333,
        "end": 22.3
      },
      {
        "id": "v07.1",
        "text": "That is the heart",
        "start": 22.666666666666668,
        "end": 23.566666666666666
      },
      {
        "id": "v07.2",
        "text": "of Diwali: light over",
        "start": 23.566666666666666,
        "end": 24.466666666666665
      },
      {
        "id": "v07.3",
        "text": "darkness, good over evil,",
        "start": 24.466666666666665,
        "end": 26.2
      },
      {
        "id": "v08.1",
        "text": "and a home that",
        "start": 26.666666666666668,
        "end": 27.566666666666666
      },
      {
        "id": "v08.2",
        "text": "keeps a lamp burning.",
        "start": 27.566666666666666,
        "end": 28.46666666666667
      },
      {
        "id": "v09.1",
        "text": "The festival is five",
        "start": 28.233333333333334,
        "end": 29.133333333333333
      },
      {
        "id": "v09.2",
        "text": "days: Dhanteras, Chhoti Diwali,",
        "start": 29.133333333333333,
        "end": 30.033333333333335
      },
      {
        "id": "v09.3",
        "text": "Lakshmi Puja,",
        "start": 30.033333333333335,
        "end": 33.233333333333334
      },
      {
        "id": "v10.1",
        "text": "Govardhan Puja, and Bhai",
        "start": 33.8,
        "end": 34.7
      },
      {
        "id": "v10.2",
        "text": "Dooj, the bond of",
        "start": 34.7,
        "end": 35.6
      },
      {
        "id": "v10.3",
        "text": "brothers and sisters.",
        "start": 35.6,
        "end": 37.333333333333336
      },
      {
        "id": "v11.1",
        "text": "Homes are cleaned, rangoli",
        "start": 37.93333333333333,
        "end": 38.833333333333336
      },
      {
        "id": "v11.2",
        "text": "drawn at the door,",
        "start": 38.833333333333336,
        "end": 39.733333333333334
      },
      {
        "id": "v11.3",
        "text": "sweets shared,",
        "start": 39.733333333333334,
        "end": 40.766666666666666
      },
      {
        "id": "v12.1",
        "text": "and Lakshmi welcomed with",
        "start": 41.233333333333334,
        "end": 42.13333333333333
      },
      {
        "id": "v12.2",
        "text": "lamps and a prayer",
        "start": 42.13333333333333,
        "end": 43.03333333333333
      },
      {
        "id": "v12.3",
        "text": "for prosperity and peace.",
        "start": 43.03333333333333,
        "end": 44.733333333333334
      },
      {
        "id": "v13.1",
        "text": "In the north, grain",
        "start": 45.166666666666664,
        "end": 46.06666666666667
      },
      {
        "id": "v13.2",
        "text": "and cattle are honoured",
        "start": 46.06666666666667,
        "end": 46.96666666666667
      },
      {
        "id": "v13.3",
        "text": "on Govardhan;",
        "start": 46.96666666666667,
        "end": 47.833333333333336
      },
      {
        "id": "v14.1",
        "text": "brothers and sisters mark",
        "start": 48.266666666666666,
        "end": 49.166666666666664
      },
      {
        "id": "v14.2",
        "text": "Bhai Dooj with a",
        "start": 49.166666666666664,
        "end": 50.06666666666667
      },
      {
        "id": "v14.3",
        "text": "tilak and a shared",
        "start": 50.06666666666667,
        "end": 50.96666666666667
      },
      {
        "id": "v14.4",
        "text": "meal.",
        "start": 50.96666666666667,
        "end": 51.766666666666666
      },
      {
        "id": "v15.1",
        "text": "So the diya is",
        "start": 52.233333333333334,
        "end": 53.13333333333333
      },
      {
        "id": "v15.2",
        "text": "not only a lamp.",
        "start": 53.13333333333333,
        "end": 54.03333333333333
      },
      {
        "id": "v16.1",
        "text": "It is a city",
        "start": 54.2,
        "end": 55.1
      },
      {
        "id": "v16.2",
        "text": "remembering, a family giving,",
        "start": 55.1,
        "end": 56
      },
      {
        "id": "v16.3",
        "text": "and a promise that",
        "start": 56,
        "end": 56.9
      },
      {
        "id": "v16.4",
        "text": "light returns to every",
        "start": 56.9,
        "end": 57.8
      },
      {
        "id": "v16.5",
        "text": "home.",
        "start": 57.8,
        "end": 59.1
      }
    ]
  },
